# Pasa de listas de materiales sin cantidad (M2M) a requerimientos con cantidad y anticipación,
# tanto en la receta (MaterialOperacion) como copiados en cada fase de lote (MaterialFase).
# Los registros previos no tenían cantidad: se migran con cantidad 1.

from decimal import Decimal

import django.db.models.deletion
from django.db import migrations, models


def copiar_materiales(apps, schema_editor):
    OperacionProceso = apps.get_model('procesos', 'OperacionProceso')
    FaseLote = apps.get_model('procesos', 'FaseLote')
    MaterialOperacion = apps.get_model('procesos', 'MaterialOperacion')
    MaterialFase = apps.get_model('procesos', 'MaterialFase')
    uno = Decimal('1')

    for op in OperacionProceso.objects.prefetch_related('materiales_requeridos'):
        for material in op.materiales_requeridos.all():
            MaterialOperacion.objects.create(operacion=op, material=material, cantidad=uno)

    for fase in FaseLote.objects.select_related('operacion_maestra').prefetch_related(
        'operacion_maestra__materiales_requeridos', 'materiales_asignados'
    ):
        de_receta = [] if fase.es_subtarea_muestreo else list(fase.operacion_maestra.materiales_requeridos.all())
        for material in de_receta:
            MaterialFase.objects.create(fase=fase, material=material, cantidad=uno, cantidad_receta=uno)
        for material in fase.materiales_asignados.all():
            if material not in de_receta:
                MaterialFase.objects.create(
                    fase=fase, material=material, cantidad=uno,
                    motivo_ajuste='Migrado de la asignación manual previa (sin cantidad registrada).',
                )


def restaurar_listas(apps, schema_editor):
    MaterialOperacion = apps.get_model('procesos', 'MaterialOperacion')
    MaterialFase = apps.get_model('procesos', 'MaterialFase')
    for mo in MaterialOperacion.objects.select_related('operacion'):
        mo.operacion.materiales_requeridos.add(mo.material_id)
    for mf in MaterialFase.objects.filter(activo=True, cantidad_receta__isnull=True).select_related('fase'):
        mf.fase.materiales_asignados.add(mf.material_id)


